// apply-update.mjs
// Updates an existing Agent Flow Builder folder to the newest version.
//
//   1. Put this file inside your agent-flow-builder folder (next to package.json).
//   2. Open a terminal in that folder and run:   node apply-update.mjs
//   3. Check it:   npm test
//
// It only touches the 17 files listed below. Your other files, node_modules and
// package-lock.json are left alone. It is safe to run twice.
//
// What is new in this version:
//   - New agents you add by clicking line up in a tidy column beside the Supervisor
//   - A "What is your team for?" box in the Custom domain
//   - Netlify settings (netlify.toml, .nvmrc) and a check-only GitHub workflow (ci.yml)

import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));

// Safety check: only run inside the project.
const pkg = join(root, 'package.json');
let name = '';
try { name = JSON.parse(readFileSync(pkg, 'utf8')).name; } catch {}
if (name !== 'agent-flow-builder') {
  console.error('This file is not inside the agent-flow-builder folder.');
  console.error('Move it next to package.json and run it again.');
  process.exit(1);
}

const FILES = {
 "src/logic/placement.ts": "import type { AgentNode, NodeType } from '../types';\nimport { CANVAS_H, CANVAS_W, NODE_H, NODE_W } from './constants';\n\n/** Same spacing a ready-made team uses, so hand-built teams look the same. */\nconst STEP = NODE_H + 28;\nconst MARGIN = 12;\n\n/**\n * Where to put a new agent that was added by clicking.\n * Agents line up in a column to the right of the Supervisor, each one below the last.\n * When a column is full the next one starts to its right. `base` is the top-left of what you can see.\n */\nexport function findFreeSpot(nodes: AgentNode[], type: NodeType, base: { x: number; y: number }): { x: number; y: number } {\n  const sup = nodes.find((n) => n.type === 'supervisor');\n  const besideSupervisor = type === 'agent' && !!sup;\n  const startX = besideSupervisor && sup ? sup.x + 260 : base.x;\n  const startY = besideSupervisor && sup ? sup.y : base.y;\n  const maxX = CANVAS_W - NODE_W - 8;\n  const maxY = CANVAS_H - NODE_H - 8;\n  const free = (x: number, y: number) => nodes.every((n) => Math.abs(n.x - x) >= NODE_W + MARGIN || Math.abs(n.y - y) >= NODE_H + MARGIN);\n  for (let x = startX; x <= maxX; x += NODE_W + 60) {\n    for (let y = startY; y <= maxY; y += STEP) if (free(x, y)) return { x, y };\n  }\n  return { x: base.x, y: base.y }; // the canvas is full: let it overlap rather than fail\n}\n",
 "src/logic/graph.ts": "import { DOMAINS } from '../data/domains';\nimport type { AgentNode, Edge, Graph, MyAgent, NodeOpts, NodeType, PaletteItem } from '../types';\nimport { KCOUNT, NODE_H } from './constants';\nimport { toolList } from './helpers';\n\n/* ---------- ids ---------- */\n\n/** One counter shared by nodes, arrows and custom agents, so ids never clash. */\nexport function makeIds(start: number) {\n  let n = start;\n  return {\n    node: () => 'n' + n++,\n    edge: () => 'e' + n++,\n    mine: () => 'm' + n++,\n    next: () => n,\n  };\n}\n\nexport type BuiltGraph = Graph & { nextId: number };\n\n/* ---------- palette items for a domain ---------- */\n\n/** The supervisor plus every ready-made agent for a domain. Names can be overridden by the learner. */\nexport function domItems(dk: string, overrides: Record<string, string>): PaletteItem[] {\n  const d = DOMAINS[dk];\n  const items: PaletteItem[] = [\n    { key: dk + ':sup', kind: 'supervisor', name: overrides[dk + ':sup'] || 'Supervisor', desc: 'Routes each request to the right agent' },\n  ];\n  d.agents.forEach((a, i) =>\n    items.push({ key: dk + ':' + i, kind: 'agent', name: overrides[dk + ':' + i] || a[0], desc: a[1], tools: a[2], color: i % KCOUNT }),\n  );\n  return items;\n}\n\n/** The starting values (prompt, tools...) for a node created from a palette item. */\nexport function itemOpts(dk: string, it: PaletteItem, team?: string): NodeOpts {\n  const d = DOMAINS[dk];\n  const t = team || d.team;\n  if (it.kind === 'supervisor') {\n    return {\n      name: it.name,\n      desc: '',\n      tools: '',\n      prompt:\n        'You are the supervisor of a ' + t + '. Read the conversation and decide which specialist should act next, based on what the user still needs. When the request has been completely handled, choose FINISH.',\n    };\n  }\n  return {\n    name: it.name,\n    desc: it.desc,\n    tools: it.tools,\n    color: it.color,\n    prompt:\n      'You are the ' + it.name + ' on a ' + t + '. Your job: ' + it.desc + ' Ask for any detail you are missing, and say clearly when your part is done.' + (d.note ? ' ' + d.note : ''),\n  };\n}\n\n/** Starting values for a node made from one of the learner's own (custom) agents. */\nexport function customAgentOpts(a: MyAgent, team?: string): NodeOpts {\n  const job = a.desc || 'Describe what this agent is responsible for.';\n  return {\n    name: a.name,\n    color: 4,\n    tools: '',\n    desc: a.desc || 'Handles ' + a.name + ' tasks.',\n    prompt: 'You are the ' + a.name + (team ? ' on a ' + team : '') + '. Your job: ' + job + ' Stay within this role. Ask for any detail you are missing, and say clearly when your part is done.',\n  };\n}\n\n/**\n * The team description to use in starting instructions.\n * In the Custom domain it comes from what the learner typed (\"cooking class\" -> \"cooking class team\").\n */\nexport function teamPhrase(dk: string, topic: string): string {\n  const t = topic.trim();\n  if (dk !== 'custom' || !t) return DOMAINS[dk].team;\n  return /\\bteam$/i.test(t) ? t : t + ' team';\n}\n\n/** Like teamPhrase, but empty when the learner has not named their team (so nothing extra is added). */\nexport function customTeam(dk: string, topic: string): string | undefined {\n  return dk === 'custom' && topic.trim() ? teamPhrase(dk, topic) : undefined;\n}\n\n/* ---------- creating nodes ---------- */\n\n/** \"Helper\" -> \"Helper 2\" when \"Helper\" already exists. */\nexport function uniqueName(nodes: AgentNode[], base: string): string {\n  if (!nodes.some((n) => n.name === base)) return base;\n  let i = 2;\n  while (nodes.some((n) => n.name === base + ' ' + i)) i++;\n  return base + ' ' + i;\n}\n\nexport function createNode(nodes: AgentNode[], id: string, type: NodeType, x: number, y: number, o: NodeOpts = {}): AgentNode {\n  const workers = nodes.filter((n) => n.type !== 'supervisor').length;\n  return {\n    id,\n    type,\n    x,\n    y,\n    name: uniqueName(nodes, o.name || (type === 'supervisor' ? 'Supervisor' : 'New Agent')),\n    desc: o.desc ?? '',\n    tools: o.tools ?? '',\n    prompt: o.prompt ?? 'You are a helpful specialist agent. Describe your job here, what you should do, and what you should not do.',\n    color: o.color ?? workers % KCOUNT,\n  };\n}\n\n/** An agent is a \"router\" when at least one of its outgoing arrows has a condition. */\nexport function isRouterNode(nodes: AgentNode[], edges: Edge[], id: string): boolean {\n  const n = nodes.find((x) => x.id === id);\n  if (!n || n.type === 'supervisor') return false;\n  return edges.some((e) => {\n    if (e.from !== id || !(e.when || '').trim()) return false;\n    const t = nodes.find((x) => x.id === e.to);\n    return !!t && t.type !== 'supervisor';\n  });\n}\n\n/* ---------- ready-made teams and examples ---------- */\n\n/** Loads a whole domain: a supervisor, every agent, and the arrows between them. */\nexport function buildTeam(dk: string, overrides: Record<string, string>, startId: number): BuiltGraph {\n  const ids = makeIds(startId);\n  const nodes: AgentNode[] = [];\n  const edges: Edge[] = [];\n  const add = (type: NodeType, x: number, y: number, o: NodeOpts) => {\n    const n = createNode(nodes, ids.node(), type, x, y, o);\n    nodes.push(n);\n    return n;\n  };\n  const items = domItems(dk, overrides);\n  const ws = items.slice(1);\n  const gap = 92;\n  const center = 450;\n  const flows = (DOMAINS[dk].flows || []).filter(([a, b]) => ws[a] && ws[b]);\n  // columns: an agent that receives a conditional arrow sits one column to the right of its source\n  const depth = ws.map(() => 0);\n  for (let pass = 0; pass < ws.length; pass++) flows.forEach(([a, b]) => { depth[b] = Math.max(depth[b], depth[a] + 1); });\n  const cols: Record<number, number[]> = {};\n  ws.forEach((_, i) => (cols[depth[i]] = cols[depth[i]] || []).push(i));\n  const sup = add('supervisor', 40, center - NODE_H / 2, itemOpts(dk, items[0]));\n  const wn: AgentNode[] = [];\n  Object.keys(cols).forEach((key) => {\n    const d = Number(key);\n    const list = cols[d];\n    list.forEach((i, k) => {\n      wn[i] = add('agent', 300 + d * 310, center - NODE_H / 2 + (k - (list.length - 1) / 2) * gap, itemOpts(dk, ws[i]));\n    });\n  });\n  wn.forEach((w) => edges.push({ id: ids.edge(), from: sup.id, to: w.id, when: '' }));\n  flows.forEach(([a, b, when]) => edges.push({ id: ids.edge(), from: wn[a].id, to: wn[b].id, when }));\n  return { nodes, edges, nextId: ids.next() };\n}\n\nexport type ExampleKind = 'tiny' | 'loop';\n\n/** Small graphs for beginners: a supervisor with two agents, or a writer/reviewer loop. */\nexport function buildExample(kind: ExampleKind, startId: number): BuiltGraph {\n  const ids = makeIds(startId);\n  const nodes: AgentNode[] = [];\n  const edges: Edge[] = [];\n  const g = domItems('general', {});\n  const opt = (it: PaletteItem): NodeOpts => ({ ...itemOpts('general', it), tools: '' });\n  const add = (type: NodeType, x: number, y: number, o: NodeOpts) => {\n    const n = createNode(nodes, ids.node(), type, x, y, o);\n    nodes.push(n);\n    return n;\n  };\n  const link = (a: AgentNode, b: AgentNode, when = '') => edges.push({ id: ids.edge(), from: a.id, to: b.id, when });\n  if (kind === 'tiny') {\n    const s = add('supervisor', 40, 170, itemOpts('general', g[0]));\n    const a = add('agent', 300, 80, opt(g[2]));\n    const b = add('agent', 300, 250, opt(g[3]));\n    link(s, a);\n    link(s, b);\n  } else {\n    const s = add('supervisor', 40, 150, itemOpts('general', g[0]));\n    const w = add('agent', 300, 150, opt(g[3]));\n    const r = add('agent', 620, 150, opt(g[4]));\n    link(s, w);\n    link(w, r);\n    link(r, w, 'the draft needs fixes');\n  }\n  return { nodes, edges, nextId: ids.next() };\n}\n\n/** The small grey line under a node's name on the canvas. */\nexport function nodeSubtitle(n: AgentNode, nodes: AgentNode[], edges: Edge[]): string {\n  if (n.type === 'supervisor') {\n    const c = edges.filter((e) => e.from === n.id).length;\n    return c ? `routes to ${c} agent${c > 1 ? 's' : ''}` : 'router';\n  }\n  const parts: string[] = [];\n  const t = toolList(n.tools).length;\n  if (t) parts.push(`${t} tool${t > 1 ? 's' : ''}`);\n  if (isRouterNode(nodes, edges, n.id)) parts.push(`${edges.filter((e) => e.from === n.id).length} paths`);\n  return parts.length ? parts.join(', ') : 'no tools';\n}\n",
 "src/state/reducer.ts": "import { defaultModels } from '../data/providers';\nimport { CANVAS_H, CANVAS_W, NODE_W, NODE_H } from '../logic/constants';\nimport { buildTeam, createNode, customAgentOpts, customTeam, type BuiltGraph } from '../logic/graph';\nimport type { LoadedSave } from '../logic/saveFile';\nimport type { AgentNode, Edge, MyAgent, NodeOpts, NodeType, ProviderKey, Selection, SimAction, SimSession, TabName } from '../types';\n\nexport type HlSpec = { type: 'sel' } | { type: 'section'; key: string };\nexport type FocusField = 'name' | 'when' | null;\n\nexport interface AppState {\n  /* the graph the learner draws */\n  nodes: AgentNode[];\n  edges: Edge[];\n  nextId: number;\n  sel: Selection;\n  /* palette */\n  domain: string;\n  overrides: Record<string, string>;\n  myAgents: MyAgent[];\n  /** what the team is for (used by the Custom domain in starting instructions) */\n  teamName: string;\n  /* code settings */\n  provider: ProviderKey;\n  models: Record<ProviderKey, string>;\n  explain: boolean;\n  /* interface */\n  tab: TabName;\n  hl: HlSpec;\n  /** bump to ask the code view to scroll to the highlighted lines */\n  scrollTick: number;\n  focusField: FocusField;\n  /** bump to ask the canvas to fit everything in view */\n  fitTick: number;\n  wide: boolean;\n  /** which sections of the Learn tab are open */\n  learnOpen: Record<string, boolean>;\n  /** bump to ask the Learn tab to scroll to the \"run it\" steps */\n  howtoTick: number;\n  /** true once the first-click tip has been shown */\n  tipShown: boolean;\n  /* simulator */\n  sim: SimSession | null;\n  simPlaying: boolean;\n}\n\nexport type Action =\n  | { type: 'select'; sel: Selection }\n  | { type: 'edit'; sel: NonNullable<Selection>; field: FocusField }\n  | { type: 'clear-focus-field' }\n  | { type: 'set-tab'; tab: TabName }\n  | { type: 'show-code' }\n  | { type: 'show-section'; key: string }\n  | { type: 'clear-hl' }\n  | { type: 'toggle-wide' }\n  | { type: 'learn-toggle'; key: string; open: boolean }\n  | { type: 'show-howto' }\n  | { type: 'add-node'; nodeType: NodeType; x: number; y: number; opts?: NodeOpts }\n  | { type: 'create-custom-agent'; name: string; desc: string; x: number; y: number }\n  | { type: 'move-node'; id: string; x: number; y: number }\n  | { type: 'update-node'; id: string; patch: Partial<Pick<AgentNode, 'name' | 'desc' | 'prompt' | 'tools'>> }\n  | { type: 'delete-selection' }\n  | { type: 'delete-edge'; id: string }\n  | { type: 'add-edge'; from: string; to: string }\n  | { type: 'update-edge'; id: string; when: string }\n  | { type: 'load-graph'; graph: BuiltGraph }\n  | { type: 'clear-canvas' }\n  | { type: 'open-save'; loaded: LoadedSave }\n  | { type: 'set-domain'; domain: string }\n  | { type: 'set-team-name'; value: string }\n  | { type: 'rename-override'; key: string; name: string }\n  | { type: 'rename-my-agent'; id: string; name: string }\n  | { type: 'remove-my-agent'; id: string }\n  | { type: 'set-provider'; provider: ProviderKey }\n  | { type: 'set-model'; value: string }\n  | { type: 'set-explain'; value: boolean }\n  | { type: 'sim-start'; request: string; sig: string }\n  | { type: 'sim-act'; action: SimAction }\n  | { type: 'sim-back' }\n  | { type: 'sim-reset' }\n  | { type: 'sim-play'; on: boolean };\n\nexport function initialState(): AppState {\n  const built = buildTeam('hospitality', {}, 1);\n  return {\n    nodes: built.nodes,\n    edges: built.edges,\n    nextId: built.nextId,\n    sel: null,\n    domain: 'hospitality',\n    overrides: {},\n    myAgents: [],\n    teamName: '',\n    provider: 'gemini',\n    models: defaultModels(),\n    explain: true,\n    tab: 'learn',\n    hl: { type: 'sel' },\n    scrollTick: 0,\n    focusField: null,\n    fitTick: 1,\n    wide: false,\n    learnOpen: {},\n    howtoTick: 0,\n    tipShown: false,\n    sim: null,\n    simPlaying: false,\n  };\n}\n\nconst clampX = (x: number) => Math.max(8, Math.min(CANVAS_W - NODE_W - 8, x));\nconst clampY = (y: number) => Math.max(8, Math.min(CANVAS_H - NODE_H - 8, y));\n\n/** Selecting something highlights its code. From the Learn tab it also jumps to the Code tab. */\nfunction withSelection(s: AppState, sel: Selection): AppState {\n  const tab = sel && s.tab === 'learn' ? 'code' : s.tab;\n  return {\n    ...s,\n    sel,\n    hl: { type: 'sel' },\n    tab,\n    scrollTick: sel ? s.scrollTick + 1 : s.scrollTick,\n    // the first time something is selected on the Code tab, remind the learner how to edit\n    tipShown: s.tipShown || (!!sel && tab === 'code'),\n  };\n}\n\nexport function reducer(s: AppState, a: Action): AppState {\n  switch (a.type) {\n    case 'select':\n      return withSelection(s, a.sel);\n    case 'edit':\n      return { ...s, sel: a.sel, hl: { type: 'sel' }, tab: 'agent', focusField: a.field };\n    case 'clear-focus-field':\n      return s.focusField ? { ...s, focusField: null } : s;\n    case 'set-tab':\n      return { ...s, tab: a.tab, scrollTick: a.tab === 'code' ? s.scrollTick + 1 : s.scrollTick };\n    case 'show-code':\n      return { ...s, hl: { type: 'sel' }, tab: 'code', scrollTick: s.scrollTick + 1 };\n    case 'show-section':\n      return { ...s, hl: { type: 'section', key: a.key }, tab: 'code', scrollTick: s.scrollTick + 1 };\n    case 'clear-hl':\n      return { ...s, hl: { type: 'sel' } };\n    case 'toggle-wide':\n      return { ...s, wide: !s.wide };\n    case 'learn-toggle':\n      return { ...s, learnOpen: { ...s.learnOpen, [a.key]: a.open } };\n    case 'show-howto':\n      return { ...s, tab: 'learn', learnOpen: { ...s.learnOpen, run: true }, howtoTick: s.howtoTick + 1 };\n\n    case 'add-node': {\n      if (a.nodeType === 'supervisor' && s.nodes.some((n) => n.type === 'supervisor')) return s;\n      const id = 'n' + s.nextId;\n      const node = createNode(s.nodes, id, a.nodeType, clampX(a.x), clampY(a.y), a.opts);\n      return withSelection({ ...s, nodes: [...s.nodes, node], nextId: s.nextId + 1 }, { k: 'node', id });\n    }\n    case 'create-custom-agent': {\n      const agent: MyAgent = { id: 'm' + s.nextId, name: a.name, desc: a.desc };\n      const nid = 'n' + (s.nextId + 1);\n      const node = createNode(s.nodes, nid, 'agent', clampX(a.x), clampY(a.y), customAgentOpts(agent, customTeam(s.domain, s.teamName)));\n      return withSelection({ ...s, myAgents: [...s.myAgents, agent], nodes: [...s.nodes, node], nextId: s.nextId + 2 }, { k: 'node', id: nid });\n    }\n    case 'move-node':\n      return { ...s, nodes: s.nodes.map((n) => (n.id === a.id ? { ...n, x: clampX(a.x), y: clampY(a.y) } : n)) };\n    case 'update-node':\n      return { ...s, nodes: s.nodes.map((n) => (n.id === a.id ? { ...n, ...a.patch } : n)) };\n\n    case 'delete-selection': {\n      if (!s.sel) return s;\n      const { k, id } = s.sel;\n      if (k === 'node') return { ...s, nodes: s.nodes.filter((n) => n.id !== id), edges: s.edges.filter((e) => e.from !== id && e.to !== id), sel: null };\n      return { ...s, edges: s.edges.filter((e) => e.id !== id), sel: null };\n    }\n    case 'delete-edge':\n      return { ...s, edges: s.edges.filter((e) => e.id !== a.id), sel: s.sel && s.sel.k === 'edge' && s.sel.id === a.id ? null : s.sel };\n    case 'add-edge':\n      return { ...s, edges: [...s.edges, { id: 'e' + s.nextId, from: a.from, to: a.to, when: '' }], nextId: s.nextId + 1 };\n    case 'update-edge':\n      return { ...s, edges: s.edges.map((e) => (e.id === a.id ? { ...e, when: a.when } : e)) };\n\n    case 'load-graph':\n      return { ...s, nodes: a.graph.nodes, edges: a.graph.edges, nextId: a.graph.nextId, sel: null, hl: { type: 'sel' }, fitTick: s.fitTick + 1 };\n    case 'clear-canvas':\n      return { ...s, nodes: [], edges: [], sel: null, hl: { type: 'sel' }, fitTick: s.fitTick + 1 };\n    case 'open-save': {\n      const l = a.loaded;\n      return {\n        ...s,\n        nodes: l.nodes,\n        edges: l.edges,\n        nextId: l.nextId,\n        sel: null,\n        hl: { type: 'sel' },\n        myAgents: l.myAgents,\n        overrides: l.overrides,\n        teamName: l.teamName,\n        domain: l.domain ?? s.domain,\n        provider: l.provider ?? s.provider,\n        models: { ...s.models, ...l.models },\n        fitTick: s.fitTick + 1,\n      };\n    }\n\n    case 'set-domain':\n      return { ...s, domain: a.domain };\n    case 'set-team-name':\n      return { ...s, teamName: a.value };\n    case 'rename-override':\n      return { ...s, overrides: { ...s.overrides, [a.key]: a.name } };\n    case 'rename-my-agent':\n      return { ...s, myAgents: s.myAgents.map((m) => (m.id === a.id ? { ...m, name: a.name } : m)) };\n    case 'remove-my-agent':\n      return { ...s, myAgents: s.myAgents.filter((m) => m.id !== a.id) };\n\n    case 'set-provider':\n      return { ...s, provider: a.provider };\n    case 'set-model':\n      return { ...s, models: { ...s.models, [s.provider]: a.value } };\n    case 'set-explain':\n      return { ...s, explain: a.value };\n\n    case 'sim-start':\n      return { ...s, sim: { request: a.request, actions: [], sig: a.sig }, simPlaying: false };\n    case 'sim-act':\n      return s.sim ? { ...s, sim: { ...s.sim, actions: [...s.sim.actions, a.action] } } : s;\n    case 'sim-back':\n      return s.sim && s.sim.actions.length ? { ...s, sim: { ...s.sim, actions: s.sim.actions.slice(0, -1) }, simPlaying: false } : s;\n    case 'sim-reset':\n      return { ...s, sim: null, simPlaying: false };\n    case 'sim-play':\n      return { ...s, simPlaying: a.on };\n  }\n}\n",
 "src/types.ts": "/* Shared types for the whole app. Keep this file free of runtime code. */\n\nexport type NodeType = 'supervisor' | 'agent';\nexport type ProviderKey = 'gemini' | 'claude' | 'openai' | 'ollama';\nexport type TabName = 'learn' | 'code' | 'sim' | 'agent';\n\n/* ---------- the graph the learner draws ---------- */\n\nexport interface AgentNode {\n  id: string;\n  type: NodeType;\n  name: string;\n  desc: string;\n  prompt: string;\n  /** comma-separated tool names */\n  tools: string;\n  /** index into the 5 agent colours (ignored for the supervisor) */\n  color: number;\n  x: number;\n  y: number;\n}\n\nexport interface Edge {\n  id: string;\n  from: string;\n  to: string;\n  /** optional condition; empty means \"always\" */\n  when: string;\n}\n\nexport interface Graph {\n  nodes: AgentNode[];\n  edges: Edge[];\n}\n\nexport interface MyAgent {\n  id: string;\n  name: string;\n  desc: string;\n}\n\nexport type Selection = { k: 'node' | 'edge'; id: string } | null;\n\n/* ---------- static data ---------- */\n\nexport type AgentDef = [name: string, desc: string, tools: string];\n\nexport interface DomainDef {\n  label: string;\n  team: string;\n  note?: string;\n  flows?: [from: number, to: number, when: string][];\n  agents: AgentDef[];\n}\n\nexport interface ProviderDef {\n  label: string;\n  model: string;\n  pkg: string;\n  imp: string;\n  cls: string;\n  env: string;\n  keyUrl: string;\n}\n\nexport interface PaletteItem {\n  key: string;\n  kind: NodeType;\n  name: string;\n  desc: string;\n  tools?: string;\n  color?: number;\n}\n\nexport interface NodeOpts {\n  name?: string;\n  desc?: string;\n  prompt?: string;\n  tools?: string;\n  color?: number;\n}\n\n/* ---------- code generation ---------- */\n\nexport type Range = [start: number, end: number];\n\n/** Which lines of the generated code belong to which agent, arrow or section (1-based, inclusive). */\nexport interface Marks {\n  nodes: Record<string, Range[]>;\n  edges: Record<string, Range[]>;\n  sections: Record<string, Range>;\n}\n\nexport type WorkerMode = 'router' | 'chain' | 'back' | 'end';\n\nexport interface PlanWorker {\n  id: string;\n  name: string;\n  ident: string;\n  tools: string[];\n  mode: WorkerMode;\n  next: { edge: string; to: string }[];\n  branches: { edge: string; to: string; when: string }[];\n  hasDefault: boolean;\n}\n\n/** A compact description of the compiled graph. The explainer and the simulator both read it. */\nexport interface Plan {\n  sup: { id: string; name: string } | null;\n  limit: number;\n  done: 'supervisor' | 'END';\n  entries: string[];\n  routes: { edge: string; to: string; when: string }[];\n  workers: Record<string, PlanWorker>;\n}\n\nexport interface SetupInfo {\n  pkg: string;\n  pyd: boolean;\n  env: string;\n  keyUrl: string;\n  model: string;\n  label: string;\n  tools: boolean;\n}\n\nexport interface GenConfig {\n  provider: ProviderKey;\n  models: Record<ProviderKey, string>;\n  explain: boolean;\n}\n\nexport interface GenResult {\n  code: string;\n  warnings: string[];\n  notes: string[];\n  marks: Marks;\n  plan: Plan | null;\n  setup: SetupInfo | null;\n  meta: string;\n}\n\n/* ---------- simulation ---------- */\n\nexport interface SimOption {\n  value: string;\n  label: string;\n  to: string;\n  edge: string;\n  hint: string;\n}\n\nexport type SimPending =\n  | { kind: 'go'; to: string; edge: string; label: string }\n  | { kind: 'choose'; who: 'supervisor' | 'router'; node: string; options: SimOption[] };\n\nexport interface SimMessage {\n  role: 'human' | 'ai';\n  name: string;\n  text: string;\n}\n\nexport interface SimState {\n  cur: string;\n  pending: SimPending | null;\n  done: boolean;\n  error: string | null;\n  next: string | null;\n  trace: string[];\n  walked: string[];\n  visited: string[];\n  runs: number;\n  calls: number;\n  queue: { edge: string; to: string }[];\n  messages: SimMessage[];\n  title: string;\n  text: string;\n  focus: { nodes: string[]; edges: string[] };\n}\n\nexport type SimAction = 'next' | { choose: string };\n\nexport interface SimSession {\n  request: string;\n  actions: SimAction[];\n  /** signature of the plan the session started with, used to detect edits */\n  sig: string;\n}\n\n/* ---------- saved files ---------- */\n\nexport interface SavedFile {\n  v: number;\n  provider: ProviderKey;\n  models: Record<ProviderKey, string>;\n  domain: string;\n  overrides: Record<string, string>;\n  myAgents: MyAgent[];\n  /** added later; older files do not have it */\n  teamName?: string;\n  nodes: AgentNode[];\n  edges: Edge[];\n}\n",
 "src/logic/saveFile.ts": "import { DOMAINS } from '../data/domains';\nimport { PROVIDERS, PROVIDER_KEYS } from '../data/providers';\nimport type { AgentNode, Edge, MyAgent, ProviderKey, SavedFile } from '../types';\n\nexport const SAVE_VERSION = 3;\n\nexport interface SaveInput {\n  provider: ProviderKey;\n  models: Record<ProviderKey, string>;\n  domain: string;\n  overrides: Record<string, string>;\n  myAgents: MyAgent[];\n  teamName: string;\n  nodes: AgentNode[];\n  edges: Edge[];\n}\n\n/** The text of the .json file the Save button downloads. */\nexport function serializeSave(s: SaveInput): string {\n  const file: SavedFile = {\n    v: SAVE_VERSION,\n    provider: s.provider,\n    models: s.models,\n    domain: s.domain,\n    overrides: s.overrides,\n    myAgents: s.myAgents,\n    teamName: s.teamName,\n    nodes: s.nodes,\n    edges: s.edges,\n  };\n  return JSON.stringify(file, null, 2);\n}\n\nexport interface LoadedSave {\n  nodes: AgentNode[];\n  edges: Edge[];\n  myAgents: MyAgent[];\n  overrides: Record<string, string>;\n  teamName: string;\n  domain: string | null;\n  provider: ProviderKey | null;\n  models: Partial<Record<ProviderKey, string>>;\n  nextId: number;\n}\n\nconst isObj = (x: unknown): x is Record<string, unknown> => typeof x === 'object' && x !== null;\n\n/**\n * Reads a saved file. Throws if it is not a layout from this app.\n * Older saves are accepted: per-role node types become plain agents, and a single\n * \"model\" field becomes the Gemini model.\n */\nexport function parseSave(text: string): LoadedSave {\n  const d: unknown = JSON.parse(text);\n  if (!isObj(d) || !Array.isArray(d.nodes) || !Array.isArray(d.edges)) throw new Error('Not a saved layout');\n\n  const nodes: AgentNode[] = d.nodes\n    .filter((n): n is Record<string, unknown> => isObj(n) && typeof n.id === 'string')\n    .map((n) => ({\n      id: String(n.id),\n      type: n.type === 'supervisor' ? 'supervisor' : 'agent',\n      name: typeof n.name === 'string' ? n.name : 'Agent',\n      desc: typeof n.desc === 'string' ? n.desc : '',\n      prompt: typeof n.prompt === 'string' ? n.prompt : '',\n      tools: typeof n.tools === 'string' ? n.tools : '',\n      color: Number.isInteger(n.color) ? Number(n.color) : 4,\n      x: Number(n.x) || 0,\n      y: Number(n.y) || 0,\n    }));\n  const ids = new Set(nodes.map((n) => n.id));\n  const edges: Edge[] = d.edges\n    .filter((e): e is Record<string, unknown> => isObj(e) && typeof e.id === 'string' && ids.has(String(e.from)) && ids.has(String(e.to)))\n    .map((e) => ({ id: String(e.id), from: String(e.from), to: String(e.to), when: typeof e.when === 'string' ? e.when : '' }));\n  const myAgents: MyAgent[] = Array.isArray(d.myAgents)\n    ? d.myAgents\n        .filter((a): a is Record<string, unknown> => isObj(a) && typeof a.id === 'string' && typeof a.name === 'string' && a.name !== '')\n        .map((a) => ({ id: String(a.id), name: String(a.name), desc: typeof a.desc === 'string' ? a.desc : '' }))\n    : [];\n  const overrides: Record<string, string> = {};\n  if (isObj(d.overrides)) for (const [k, v] of Object.entries(d.overrides)) if (typeof v === 'string') overrides[k] = v;\n\n  const models: Partial<Record<ProviderKey, string>> = {};\n  if (isObj(d.models)) {\n    for (const k of PROVIDER_KEYS) {\n      const v = d.models[k];\n      if (typeof v === 'string' && v) models[k] = v;\n    }\n  } else if (typeof d.model === 'string' && d.model) {\n    models.gemini = d.model; // saves from the first version were Gemini only\n  }\n  let provider: ProviderKey | null = null;\n  if (typeof d.provider === 'string' && d.provider in PROVIDERS) provider = d.provider as ProviderKey;\n  else if (!isObj(d.models) && typeof d.model === 'string') provider = 'gemini';\n\n  const domain = typeof d.domain === 'string' && d.domain in DOMAINS ? d.domain : null;\n  const maxId = Math.max(0, ...[...nodes, ...edges, ...myAgents].map((x) => parseInt(x.id.slice(1), 10) || 0));\n  const teamName = typeof d.teamName === 'string' ? d.teamName : '';\n  return { nodes, edges, myAgents, overrides, teamName, domain, provider, models, nextId: maxId + 1 };\n}\n",
 "src/hooks/useActions.ts": "import { DOMAINS } from '../data/domains';\nimport { checkConnection, connectedMessage } from '../logic/connect';\nimport { buildExample, buildTeam, type ExampleKind } from '../logic/graph';\nimport { findFreeSpot } from '../logic/placement';\nimport { parseSave, serializeSave } from '../logic/saveFile';\nimport { useApp } from '../state/AppContext';\nimport { useCanvasApi } from '../state/CanvasApi';\nimport { useToast } from '../state/ToastContext';\nimport type { NodeOpts, NodeType } from '../types';\nimport { copyText } from '../utils/clipboard';\nimport { downloadText } from '../utils/download';\n\nexport interface Actions {\n  addNode(type: NodeType, pos: { x: number; y: number } | null, opts?: NodeOpts): void;\n  /** returns true when the agent was created */\n  createCustomAgent(name: string, desc: string): boolean;\n  connect(fromId: string, toId: string): void;\n  loadTeam(): void;\n  loadExample(kind: ExampleKind): void;\n  save(): void;\n  openFile(file: File): Promise<void>;\n  copyCode(): Promise<void>;\n  downloadCode(): void;\n}\n\n/**\n * Things the learner can do that need a check or a message, not just a state change.\n * The returned object is rebuilt on every render, so it always sees the newest state.\n */\nexport function useActions(): Actions {\n  const { state, dispatch, gen } = useApp();\n  const toast = useToast();\n  const canvas = useCanvasApi();\n\n  /** A tidy spot for an agent added by clicking: a column to the right of the Supervisor. */\n  const freeSpot = (type: NodeType) => findFreeSpot(state.nodes, type, canvas.current ? canvas.current.spot() : { x: 50, y: 50 });\n\n  return {\n    addNode(type, pos, opts) {\n      if (type === 'supervisor' && state.nodes.some((n) => n.type === 'supervisor')) {\n        toast('Only one Supervisor is supported. Connect more agents to the one you have.');\n        return;\n      }\n      const p = pos ?? freeSpot(type);\n      dispatch({ type: 'add-node', nodeType: type, x: p.x, y: p.y, opts });\n    },\n    createCustomAgent(name, desc) {\n      const n = name.trim();\n      if (!n) {\n        toast('Type a name for your agent first.');\n        return false;\n      }\n      const p = freeSpot('agent');\n      dispatch({ type: 'create-custom-agent', name: n, desc: desc.trim(), x: p.x, y: p.y });\n      return true;\n    },\n    connect(fromId, toId) {\n      const check = checkConnection(state.nodes, state.edges, fromId, toId);\n      if (!check.ok) {\n        if (check.message) toast(check.message);\n        return;\n      }\n      const a = state.nodes.find((n) => n.id === fromId);\n      const b = state.nodes.find((n) => n.id === toId);\n      dispatch({ type: 'add-edge', from: fromId, to: toId });\n      if (a && b) toast(connectedMessage(a, b));\n    },\n    loadTeam() {\n      dispatch({ type: 'load-graph', graph: buildTeam(state.domain, state.overrides, state.nextId) });\n      const flows = (DOMAINS[state.domain].flows || []).length;\n      toast(\n        'Loaded the ' + DOMAINS[state.domain].label + ' team' +\n          (flows ? ' with ' + flows + ' conditional paths. Double-click an orange arrow to edit its condition.' : '. Double-click any agent to rename it.'),\n      );\n    },\n    loadExample(kind) {\n      dispatch({ type: 'load-graph', graph: buildExample(kind, state.nextId) });\n      toast(\n        kind === 'tiny'\n          ? 'Loaded a Supervisor and two agents. Click each one, then open the Code tab.'\n          : 'Loaded a loop: the Reviewer can send work back to the Writer. Try it in Simulate.',\n      );\n    },\n    save() {\n      downloadText('agent-flow.json', serializeSave(state), 'application/json');\n      toast('Layout saved as agent-flow.json');\n    },\n    async openFile(file) {\n      try {\n        dispatch({ type: 'open-save', loaded: parseSave(await file.text()) });\n        toast('Layout loaded');\n      } catch {\n        toast(\"That file isn't a saved Agent Flow Builder layout.\");\n      }\n    },\n    async copyCode() {\n      await copyText(gen.code);\n      toast('Code copied');\n    },\n    downloadCode() {\n      downloadText('multi_agent_graph.py', gen.code, 'text/x-python');\n      toast('Saved multi_agent_graph.py');\n    },\n  };\n}\n",
 "src/components/palette/Palette.tsx": "import { useState, type PointerEvent as ReactPointerEvent } from 'react';\nimport { DOMAINS } from '../../data/domains';\nimport { useActions } from '../../hooks/useActions';\nimport { useLatest } from '../../hooks/useLatest';\nimport { NODE_H, NODE_W } from '../../logic/constants';\nimport { customAgentOpts, customTeam, domItems, itemOpts, teamPhrase } from '../../logic/graph';\nimport { useApp } from '../../state/AppContext';\nimport { useCanvasApi } from '../../state/CanvasApi';\nimport type { MyAgent, NodeOpts, NodeType } from '../../types';\nimport { CustomAgents } from './CustomAgents';\nimport { Legend } from './Legend';\nimport { LoadTeamButton } from './LoadTeamButton';\nimport { PaletteRow } from './PaletteRow';\n\n/** What is being dragged out of the palette. */\ninterface DragSpec {\n  type: NodeType;\n  opts: NodeOpts;\n  label: string;\n  /** colour class for the floating label */\n  cls: string;\n}\n\n/** The left panel: pick a domain, then drag (or click) agents onto the canvas. */\nexport function Palette() {\n  const { state, dispatch } = useApp();\n  const actions = useActions();\n  const actionsRef = useLatest(actions);\n  const canvas = useCanvasApi();\n  const [ghost, setGhost] = useState<{ x: number; y: number; spec: DragSpec } | null>(null);\n\n  const domain = DOMAINS[state.domain];\n  const items = domItems(state.domain, state.overrides);\n\n  /** Press on an agent: a short press adds it, a drag drops it where you release. */\n  const startDrag = (e: ReactPointerEvent<HTMLDivElement>, spec: DragSpec) => {\n    e.preventDefault();\n    const sx = e.clientX, sy = e.clientY;\n    let moved = false;\n    const move = (ev: PointerEvent) => {\n      if (!moved && Math.hypot(ev.clientX - sx, ev.clientY - sy) > 6) moved = true;\n      if (moved) {\n        setGhost({ x: ev.clientX, y: ev.clientY, spec });\n        const api = canvas.current;\n        if (api) api.setDropHot(api.contains(ev.clientX, ev.clientY));\n      }\n    };\n    const up = (ev: PointerEvent) => {\n      document.removeEventListener('pointermove', move);\n      document.removeEventListener('pointerup', up);\n      document.removeEventListener('pointercancel', up);\n      setGhost(null);\n      const api = canvas.current;\n      if (api) api.setDropHot(false);\n      if (!moved) {\n        actionsRef.current.addNode(spec.type, null, spec.opts);\n      } else if (api && api.contains(ev.clientX, ev.clientY)) {\n        const c = api.toCanvas(ev.clientX, ev.clientY);\n        actionsRef.current.addNode(spec.type, { x: c.x - NODE_W / 2, y: c.y - NODE_H / 2 }, spec.opts);\n      }\n    };\n    document.addEventListener('pointermove', move);\n    document.addEventListener('pointerup', up);\n    document.addEventListener('pointercancel', up);\n  };\n\n  const dragCustom = (e: ReactPointerEvent<HTMLDivElement>, a: MyAgent) =>\n    startDrag(e, { type: 'agent', opts: customAgentOpts(a, customTeam(state.domain, state.teamName)), label: a.name, cls: 'k4' });\n\n  return (\n    <aside className=\"palette\" id=\"palette\">\n      <h3>Domain</h3>\n      <select id=\"domain\" aria-label=\"Choose a domain\" value={state.domain} onChange={(e) => dispatch({ type: 'set-domain', domain: e.target.value })}>\n        {Object.keys(DOMAINS).map((k) => (\n          <option key={k} value={k}>\n            {DOMAINS[k].label}\n          </option>\n        ))}\n      </select>\n      {domain.agents.length > 0 && <LoadTeamButton />}\n      <p className=\"sub\" id=\"dnote\">\n        {domain.agents.length ? 'Drag an agent onto the canvas, or click to add. Use the pencil to rename it.' : 'Start blank: add a Supervisor, then create your own agents below.'}\n      </p>\n\n      {state.domain === 'custom' && (\n        <div className=\"teambox\">\n          <label htmlFor=\"team-name\">What is your team for?</label>\n          <input id=\"team-name\" placeholder=\"e.g. cooking class\" maxLength={40} spellCheck={false} value={state.teamName} onChange={(e) => dispatch({ type: 'set-team-name', value: e.target.value })} />\n          <p className=\"sub\">Used in the starting instructions of the Supervisor and your agents. Fill it in before you add them.</p>\n        </div>\n      )}\n\n      <div id=\"plist\">\n        {items.map((it) => {\n          const cls = it.kind === 'supervisor' ? 't-supervisor' : 'k' + it.color;\n          return (\n            <PaletteRow\n              key={it.key}\n              name={it.name}\n              desc={it.desc}\n              cls={cls}\n              onRename={(name) => dispatch({ type: 'rename-override', key: it.key, name })}\n              onDragStart={(e) => startDrag(e, { type: it.kind, opts: itemOpts(state.domain, it, teamPhrase(state.domain, state.teamName)), label: it.name, cls })}\n            />\n          );\n        })}\n      </div>\n\n      <CustomAgents onDragStart={dragCustom} />\n      <Legend />\n\n      {ghost && (\n        <div className={'ghost ' + ghost.spec.cls} style={{ left: ghost.x, top: ghost.y }}>\n          <span className=\"dot\" />\n          <span>{ghost.spec.label}</span>\n        </div>\n      )}\n    </aside>\n  );\n}\n",
 "src/styles/palette.css": "/* Left palette: domain picker, agent list, custom agent form, legend */\n\n.palette{min-width:0;border-right:1px solid var(--line);background:var(--panel);padding:14px 12px;overflow:auto}\n.palette h3{margin:0 0 6px;font-size:13px}\n.palette .sub{margin:0 0 10px;font-size:12px;color:var(--ink-3)}\n#domain{width:100%;padding:7px 8px;border:1px solid var(--line-2);border-radius:7px;background:var(--panel-2);margin-bottom:8px;font-size:13px}\n#b-team{width:100%;margin-bottom:12px}\n.pitem{display:flex;gap:9px;align-items:center;padding:7px 8px;border:1px solid var(--line);border-radius:9px;margin-bottom:6px;background:var(--panel-2);cursor:grab;touch-action:none;user-select:none}\n.pitem:hover{border-color:var(--line-2);background:var(--panel)}\n.dot{width:9px;height:9px;border-radius:50%;background:var(--c);flex:none}\n.pt{min-width:0;flex:1}\n.pitem b{display:block;font-size:13px;line-height:1.25;overflow-wrap:anywhere}\n.pitem small{color:var(--ink-3);font-size:11.5px;line-height:1.25;display:block}\n.pitem .edit,.pitem .rm{flex:none;border:0;background:none;color:var(--ink-3);padding:4px;border-radius:5px;display:grid;place-items:center;line-height:1}\n.pitem .edit:hover{color:var(--accent);background:var(--panel)}\n.pitem .rm{font-size:17px;padding:0 5px}\n.pitem .rm:hover{color:var(--danger)}\n.pr{width:100%;padding:2px 5px;border:1px solid var(--accent);border-radius:5px;background:var(--panel);font-weight:600;font-size:13px}\n.mine{margin-top:14px;padding-top:12px;border-top:1px solid var(--line)}\n.mine input{display:block;width:100%;margin:0 0 6px;padding:6px 8px;border:1px solid var(--line-2);border-radius:7px;background:var(--panel-2);font-size:12.5px}\n.mine .btn{width:100%;margin-bottom:10px}\n.howto{margin-top:14px;padding-top:12px;border-top:1px solid var(--line);font-size:12px;color:var(--ink-2)}\n.howto p{margin:0 0 8px}\n.legend{display:flex;align-items:center;gap:8px;margin:0 0 6px;font-size:12px;color:var(--ink-2)}\n.legend svg{flex:none}\n\n.teambox{margin:0 0 12px}\n.teambox label{display:block;margin-bottom:5px;font-size:12px;font-weight:600;color:var(--ink-2)}\n.teambox input{display:block;width:100%;padding:6px 8px;border:1px solid var(--line-2);border-radius:7px;background:var(--panel-2);font-size:12.5px}\n.teambox .sub{margin:4px 0 0}\n",
 "tests/placement.test.ts": "import { describe, expect, it } from 'vitest';\nimport { CANVAS_H, NODE_H, NODE_W } from '../src/logic/constants';\nimport { buildTeam, createNode } from '../src/logic/graph';\nimport { findFreeSpot } from '../src/logic/placement';\nimport type { AgentNode, NodeType } from '../src/types';\n\n/** Adds agents one after another, the way clicking in the palette does. */\nfunction addMany(types: NodeType[], base = { x: 50, y: 50 }): AgentNode[] {\n  const nodes: AgentNode[] = [];\n  types.forEach((t, i) => {\n    const p = findFreeSpot(nodes, t, base);\n    nodes.push(createNode(nodes, 'n' + (i + 1), t, p.x, p.y, { name: t + i }));\n  });\n  return nodes;\n}\nconst overlap = (a: AgentNode, b: AgentNode) => Math.abs(a.x - b.x) < NODE_W && Math.abs(a.y - b.y) < NODE_H;\n\ndescribe('findFreeSpot', () => {\n  it('puts the first agent where you are looking', () => {\n    expect(findFreeSpot([], 'supervisor', { x: 70, y: 90 })).toEqual({ x: 70, y: 90 });\n  });\n  it('lines agents up in a column to the right of the Supervisor', () => {\n    const [sup, a, b, c] = addMany(['supervisor', 'agent', 'agent', 'agent']);\n    expect(a.x).toBe(sup.x + 260);\n    expect(a.y).toBe(sup.y);\n    expect([b.x, c.x]).toEqual([a.x, a.x]);\n    expect(b.y).toBe(a.y + NODE_H + 28);\n    expect(c.y).toBe(b.y + NODE_H + 28);\n  });\n  it('follows the Supervisor if it has been moved', () => {\n    const sup = createNode([], 'n1', 'supervisor', 500, 300, {});\n    const p = findFreeSpot([sup], 'agent', { x: 50, y: 50 });\n    expect(p).toEqual({ x: 760, y: 300 });\n  });\n  it('never overlaps, even with many agents (it starts a second column)', () => {\n    const nodes = addMany(['supervisor', ...Array<NodeType>(20).fill('agent')]);\n    for (let i = 0; i < nodes.length; i++) for (let j = i + 1; j < nodes.length; j++) expect(overlap(nodes[i], nodes[j])).toBe(false);\n    expect(new Set(nodes.filter((n) => n.type === 'agent').map((n) => n.x)).size).toBeGreaterThan(1);\n    expect(nodes.every((n) => n.y <= CANVAS_H - NODE_H - 8)).toBe(true);\n  });\n  it('without a Supervisor, agents stack in a column from the visible corner', () => {\n    const [a, b] = addMany(['agent', 'agent'], { x: 120, y: 80 });\n    expect(a).toMatchObject({ x: 120, y: 80 });\n    expect(b.x).toBe(120);\n    expect(b.y).toBe(80 + NODE_H + 28);\n  });\n  it('steps around the agents of a loaded team', () => {\n    const t = buildTeam('hospitality', {}, 1);\n    const p = findFreeSpot(t.nodes, 'agent', { x: 50, y: 50 });\n    expect(t.nodes.some((n) => Math.abs(n.x - p.x) < NODE_W + 12 && Math.abs(n.y - p.y) < NODE_H + 12)).toBe(false);\n  });\n});\n",
 "tests/reducer.test.ts": "import { describe, expect, it } from 'vitest';\nimport { checkConnection } from '../src/logic/connect';\nimport { buildExample } from '../src/logic/graph';\nimport { initialState, reducer, type AppState } from '../src/state/reducer';\n\nconst run = (s: AppState, ...actions: Parameters<typeof reducer>[1][]) => actions.reduce(reducer, s);\n\ndescribe('reducer', () => {\n  it('starts with the hospitality team and the Learn tab open', () => {\n    const s = initialState();\n    expect(s.tab).toBe('learn');\n    expect(s.nodes[0].type).toBe('supervisor');\n    expect(s.nodes.length).toBe(8);\n    expect(s.edges.some((e) => e.when)).toBe(true);\n  });\n  it('selecting from the Learn tab jumps to the Code tab and asks it to scroll', () => {\n    const s0 = initialState();\n    const s = reducer(s0, { type: 'select', sel: { k: 'node', id: s0.nodes[1].id } });\n    expect(s.tab).toBe('code');\n    expect(s.scrollTick).toBe(s0.scrollTick + 1);\n  });\n  it('selecting on the Code tab keeps the tab', () => {\n    let s = reducer(initialState(), { type: 'set-tab', tab: 'code' });\n    s = reducer(s, { type: 'select', sel: { k: 'node', id: s.nodes[1].id } });\n    expect(s.tab).toBe('code');\n  });\n  it('editing opens the Agent tab and remembers which field to focus', () => {\n    const s0 = initialState();\n    const s = reducer(s0, { type: 'edit', sel: { k: 'node', id: s0.nodes[1].id }, field: 'name' });\n    expect(s.tab).toBe('agent');\n    expect(s.focusField).toBe('name');\n    expect(reducer(s, { type: 'clear-focus-field' }).focusField).toBeNull();\n  });\n  it('adds an agent, selects it, and gives it a unique name', () => {\n    const s0 = initialState();\n    const s = run(s0, { type: 'add-node', nodeType: 'agent', x: 100, y: 100, opts: { name: 'Billing Agent' } });\n    expect(s.nodes.length).toBe(s0.nodes.length + 1);\n    expect(s.nodes[s.nodes.length - 1].name).toBe('Billing Agent 2');\n    expect(s.sel).toEqual({ k: 'node', id: s.nodes[s.nodes.length - 1].id });\n    expect(s.nextId).toBe(s0.nextId + 1);\n  });\n  it('allows only one supervisor', () => {\n    const s0 = initialState();\n    expect(reducer(s0, { type: 'add-node', nodeType: 'supervisor', x: 0, y: 0 })).toBe(s0);\n  });\n  it('keeps agents inside the canvas', () => {\n    const s = run(initialState(), { type: 'add-node', nodeType: 'agent', x: -500, y: 99999 });\n    const n = s.nodes[s.nodes.length - 1];\n    expect(n.x).toBe(8);\n    expect(n.y).toBeLessThan(900);\n  });\n  it('creates a custom agent in the palette and on the canvas in one step', () => {\n    const s = run(initialState(), { type: 'create-custom-agent', name: 'Refund Agent', desc: 'Handles refunds', x: 50, y: 50 });\n    expect(s.myAgents.map((m) => m.name)).toEqual(['Refund Agent']);\n    expect(s.nodes[s.nodes.length - 1].name).toBe('Refund Agent');\n    expect(new Set([...s.nodes.map((n) => n.id), ...s.edges.map((e) => e.id), ...s.myAgents.map((m) => m.id)]).size).toBe(s.nodes.length + s.edges.length + s.myAgents.length);\n  });\n  it('deleting an agent also removes its arrows', () => {\n    const s0 = initialState();\n    const id = s0.nodes[1].id;\n    const s = run(s0, { type: 'select', sel: { k: 'node', id } }, { type: 'delete-selection' });\n    expect(s.nodes.find((n) => n.id === id)).toBeUndefined();\n    expect(s.edges.some((e) => e.from === id || e.to === id)).toBe(false);\n    expect(s.sel).toBeNull();\n  });\n  it('edits a condition on an arrow', () => {\n    const s0 = initialState();\n    const e = s0.edges[0];\n    expect(run(s0, { type: 'update-edge', id: e.id, when: 'hello' }).edges[0].when).toBe('hello');\n  });\n  it('the model name is remembered for each provider separately', () => {\n    let s = run(initialState(), { type: 'set-provider', provider: 'claude' }, { type: 'set-model', value: 'my-claude' }, { type: 'set-provider', provider: 'openai' });\n    expect(s.models.openai).toBe('gpt-4o-mini');\n    s = reducer(s, { type: 'set-provider', provider: 'claude' });\n    expect(s.models.claude).toBe('my-claude');\n  });\n  it('simulation actions can be added, undone and reset', () => {\n    let s = run(initialState(), { type: 'sim-start', request: 'hi', sig: 'x' }, { type: 'sim-act', action: 'next' }, { type: 'sim-act', action: { choose: 'a' } });\n    expect(s.sim!.actions).toHaveLength(2);\n    s = reducer(s, { type: 'sim-back' });\n    expect(s.sim!.actions).toEqual(['next']);\n    expect(reducer(s, { type: 'sim-reset' }).sim).toBeNull();\n  });\n  it('loading a graph asks the canvas to fit and clears the selection', () => {\n    const s0 = run(initialState(), { type: 'select', sel: { k: 'node', id: 'n1' } });\n    const s = reducer(s0, { type: 'load-graph', graph: buildExample('tiny', 1) });\n    expect(s.nodes).toHaveLength(3);\n    expect(s.sel).toBeNull();\n    expect(s.fitTick).toBe(s0.fitTick + 1);\n  });\n});\n\ndescribe('checkConnection', () => {\n  const s = initialState();\n  const [sup, a, b] = s.nodes;\n  it('allows a new arrow between agents', () => expect(checkConnection(s.nodes, s.edges, a.id, b.id)).toEqual({ ok: true }));\n  it('explains why an arrow into the supervisor is not needed', () => {\n    const r = checkConnection(s.nodes, s.edges, a.id, sup.id);\n    expect(r.ok).toBe(false);\n    expect(r.ok === false && r.message).toContain('report back to the Supervisor automatically');\n  });\n  it('rejects duplicates and self-arrows', () => {\n    expect(checkConnection(s.nodes, s.edges, sup.id, a.id)).toEqual({ ok: false, message: 'Those two are already connected.' });\n    expect(checkConnection(s.nodes, s.edges, a.id, a.id)).toEqual({ ok: false, message: null });\n  });\n});\n\ndescribe('reducer: learning features', () => {\n  it('remembers which Learn sections are open', () => {\n    const s = reducer(initialState(), { type: 'learn-toggle', key: 'read', open: true });\n    expect(s.learnOpen.read).toBe(true);\n  });\n  it('\"how do I run this\" opens the Learn tab with the run steps open', () => {\n    const s0 = reducer(initialState(), { type: 'set-tab', tab: 'code' });\n    const s = reducer(s0, { type: 'show-howto' });\n    expect(s.tab).toBe('learn');\n    expect(s.learnOpen.run).toBe(true);\n    expect(s.howtoTick).toBe(s0.howtoTick + 1);\n  });\n  it('showing a code section highlights it and switches to the Code tab', () => {\n    const s = reducer(initialState(), { type: 'show-section', key: 'routing' });\n    expect(s.tab).toBe('code');\n    expect(s.hl).toEqual({ type: 'section', key: 'routing' });\n  });\n  it('the first selection on the Code tab triggers the edit tip, once', () => {\n    let s = reducer(initialState(), { type: 'set-tab', tab: 'code' });\n    expect(s.tipShown).toBe(false);\n    s = reducer(s, { type: 'select', sel: { k: 'node', id: s.nodes[0].id } });\n    expect(s.tipShown).toBe(true);\n  });\n  it('selecting from the Learn tab also counts as the first code view', () => {\n    const s0 = initialState();\n    expect(reducer(s0, { type: 'select', sel: { k: 'node', id: s0.nodes[0].id } }).tipShown).toBe(true);\n  });\n  it('no tip while you stay on the Agent tab', () => {\n    const s0 = reducer(initialState(), { type: 'set-tab', tab: 'agent' });\n    expect(reducer(s0, { type: 'select', sel: { k: 'node', id: s0.nodes[0].id } }).tipShown).toBe(false);\n  });\n});\n\ndescribe('reducer: team name for the Custom domain', () => {\n  const custom = (s: AppState) => run(s, { type: 'set-domain', domain: 'custom' });\n\n  it('is empty to start with', () => expect(initialState().teamName).toBe(''));\n  it('is used in the prompt of an agent you create in the Custom domain', () => {\n    const s = run(initialState(), { type: 'set-domain', domain: 'custom' }, { type: 'set-team-name', value: 'cooking class' }, { type: 'create-custom-agent', name: 'Helper', desc: 'Prepares ingredients.', x: 0, y: 0 });\n    expect(s.nodes[s.nodes.length - 1].prompt).toContain('You are the Helper on a cooking class team.');\n  });\n  it('is not mentioned when it has not been filled in', () => {\n    const s = run(custom(initialState()), { type: 'create-custom-agent', name: 'Helper', desc: '', x: 0, y: 0 });\n    expect(s.nodes[s.nodes.length - 1].prompt).toContain('You are the Helper. Your job:');\n  });\n  it('is ignored in the ready-made domains', () => {\n    const s = run(initialState(), { type: 'set-team-name', value: 'cooking class' }, { type: 'create-custom-agent', name: 'Helper', desc: '', x: 0, y: 0 });\n    expect(s.nodes[s.nodes.length - 1].prompt).not.toContain('cooking class');\n  });\n});\n",
 "tests/saveFile.test.ts": "import { describe, expect, it } from 'vitest';\nimport { parseSave, serializeSave } from '../src/logic/saveFile';\nimport { initialState } from '../src/state/reducer';\n\ndescribe('save files', () => {\n  it('round-trips a design', () => {\n    const s = initialState();\n    const loaded = parseSave(serializeSave({ ...s, provider: 'claude', overrides: { 'hospitality:0': 'Booking Desk' } }));\n    expect(loaded.nodes).toEqual(s.nodes);\n    expect(loaded.edges).toEqual(s.edges);\n    expect(loaded.provider).toBe('claude');\n    expect(loaded.overrides).toEqual({ 'hospitality:0': 'Booking Desk' });\n    expect(loaded.domain).toBe('hospitality');\n    expect(loaded.nextId).toBe(s.nextId);\n  });\n  it('opens saves from the first version: role types become plain agents, one model becomes the Gemini model', () => {\n    const old = {\n      v: 2, model: 'gemini-1.5-pro', domain: 'hospitality', overrides: {}, myAgents: [],\n      nodes: [\n        { id: 'n1', type: 'supervisor', name: 'Supervisor', desc: '', prompt: 'p', tools: '', x: 40, y: 100 },\n        { id: 'n2', type: 'booking', name: 'Booking Agent', desc: 'd', prompt: 'p', tools: '', x: 300, y: 60 },\n      ],\n      edges: [{ id: 'e3', from: 'n1', to: 'n2' }],\n    };\n    const l = parseSave(JSON.stringify(old));\n    expect(l.nodes.map((n) => n.type)).toEqual(['supervisor', 'agent']);\n    expect(l.edges[0].when).toBe('');\n    expect(l.models.gemini).toBe('gemini-1.5-pro');\n    expect(l.provider).toBe('gemini');\n    expect(l.nextId).toBe(4);\n  });\n  it('drops arrows that point at missing agents', () => {\n    const l = parseSave(JSON.stringify({ nodes: [{ id: 'n1', type: 'agent', name: 'A' }], edges: [{ id: 'e2', from: 'n1', to: 'ghost' }] }));\n    expect(l.edges).toHaveLength(0);\n  });\n  it('rejects files that are not layouts', () => {\n    expect(() => parseSave('{\"hello\": 1}')).toThrow();\n    expect(() => parseSave('not json')).toThrow();\n  });\n});\n\ndescribe('save files: team name', () => {\n  it('keeps the team name', () => {\n    const s = { ...initialState(), teamName: 'cooking class' };\n    expect(parseSave(serializeSave(s)).teamName).toBe('cooking class');\n  });\n  it('older files without one open with an empty team name', () => {\n    expect(parseSave(JSON.stringify({ nodes: [], edges: [] })).teamName).toBe('');\n  });\n});\n",
 "tests/teamPhrase.test.ts": "import { describe, expect, it } from 'vitest';\nimport { customAgentOpts, customTeam, domItems, itemOpts, teamPhrase } from '../src/logic/graph';\n\ndescribe('team phrase', () => {\n  it('turns what you typed into a team description', () => {\n    expect(teamPhrase('custom', 'cooking class')).toBe('cooking class team');\n    expect(teamPhrase('custom', '  Kitchen team ')).toBe('Kitchen team');\n  });\n  it('falls back to the standard wording when empty', () => expect(teamPhrase('custom', '   ')).toBe('team of specialist agents'));\n  it('is ignored outside the Custom domain', () => expect(teamPhrase('hospitality', 'cooking class')).toBe('hotel guest-services team'));\n  it('customTeam is empty unless you are in Custom and have typed something', () => {\n    expect(customTeam('custom', '')).toBeUndefined();\n    expect(customTeam('hospitality', 'x')).toBeUndefined();\n    expect(customTeam('custom', 'x')).toBe('x team');\n  });\n  it('the Supervisor starts with your team name', () => {\n    const sup = domItems('custom', {})[0];\n    expect(itemOpts('custom', sup, teamPhrase('custom', 'cooking class')).prompt).toContain('You are the supervisor of a cooking class team.');\n  });\n  it('default prompts are unchanged when no team is given', () => {\n    const sup = domItems('custom', {})[0];\n    expect(itemOpts('custom', sup).prompt).toContain('supervisor of a team of specialist agents');\n    expect(customAgentOpts({ id: 'm1', name: 'Helper', desc: 'Helps.' }).prompt).toContain('You are the Helper. Your job: Helps.');\n  });\n});\n",
 "tests/app.test.tsx": "import { renderToString } from 'react-dom/server';\nimport { describe, expect, it } from 'vitest';\nimport App from '../src/App';\nimport { DOMAINS } from '../src/data/domains';\nimport { buildExample, buildTeam } from '../src/logic/graph';\nimport { initialState, type AppState } from '../src/state/reducer';\nimport type { TabName } from '../src/types';\n\n/** These render the whole app to a string. They catch crashes in any component without needing a browser. */\nconst render = (s: Partial<AppState> = {}) => renderToString(<App initial={{ ...initialState(), ...s }} />);\n\ndescribe('App renders', () => {\n  it('shows the page shell, palette, canvas and the Learn tab', () => {\n    const html = render();\n    for (const text of ['Agent Flow Builder', 'Load full team on canvas', 'Hospitality (hotels)', 'Billing Agent', 'Your graph in plain English', 'Start here']) {\n      expect(html).toContain(text);\n    }\n  });\n\n  for (const tab of ['learn', 'code', 'sim', 'agent'] as TabName[]) {\n    it(`the ${tab} tab`, () => expect(render({ tab }).length).toBeGreaterThan(2000));\n  }\n\n  it('the Custom domain asks what the team is for', () => {\n    const html = render({ domain: 'custom' });\n    expect(html).toContain('What is your team for?');\n    expect(render({ domain: 'hospitality' })).not.toContain('What is your team for?');\n  });\n\n  it('an empty canvas', () => {\n    const html = render({ nodes: [], edges: [] });\n    expect(html).toContain('Your canvas is empty');\n    expect(html).toContain('Add some agents');\n  });\n\n  for (const dk of Object.keys(DOMAINS)) {\n    it(`the ${dk} team, with an agent selected and every tab`, () => {\n      const g = buildTeam(dk, {}, 1);\n      for (const tab of ['learn', 'code', 'sim', 'agent'] as TabName[]) {\n        const html = render({ ...g, domain: dk, tab, sel: { k: 'node', id: g.nodes[0].id } });\n        expect(html).toContain('Agent Flow Builder');\n      }\n    });\n  }\n\n  it('an arrow selected in the editor shows its condition box', () => {\n    const s = initialState();\n    const cond = s.edges.find((e) => e.when)!;\n    const html = render({ tab: 'agent', sel: { k: 'edge', id: cond.id } });\n    expect(html).toContain('Take this path only when');\n    expect(html).toContain(cond.when);\n  });\n\n  it('the Code tab marks highlighted lines for the selected agent', () => {\n    const s = initialState();\n    const html = render({ tab: 'code', sel: { k: 'node', id: s.nodes[1].id } });\n    expect(html).toContain('ln hl');\n    expect(html).toContain('Highlighted: the code for');\n  });\n\n  it('a running simulation shows its step and the code involved', () => {\n    const html = render({ tab: 'sim', sim: { request: 'hi', actions: ['next'], sig: '' } });\n    expect(html).toContain('Supervisor decides');\n    expect(html).toContain('Function that runs');\n  });\n\n  it('a finished simulation', () => {\n    const html = render({ tab: 'sim', ...buildExample('tiny', 1), sim: { request: 'hi', actions: ['next', { choose: 'writer_agent' }, 'next', 'next', { choose: 'FINISH' }, 'next'], sig: '' } });\n    expect(html).toContain('Run finished');\n  });\n});\n",
 ".nvmrc": "22\n",
 "netlify.toml": "# Settings for hosting on Netlify. Netlify reads this file automatically.\n\n[build]\n  command = \"npm run build\"\n  publish = \"dist\"\n\n[build.environment]\n  NODE_VERSION = \"22\"\n\n# Built files have a hash in their names, so browsers may keep them for a year.\n[[headers]]\n  for = \"/assets/*\"\n  [headers.values]\n    Cache-Control = \"public, max-age=31536000, immutable\"\n",
 ".github/workflows/ci.yml": "# Checks the project on every push and pull request: types, tests and a build.\n# It does not publish anything: Netlify builds and publishes the site by itself.\nname: CI\n\non:\n  push:\n    branches: [main]\n  pull_request:\n\njobs:\n  check:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n      # After your first `npm install`, commit package-lock.json and change this to `npm ci`.\n      - run: npm install\n      - run: npm run typecheck\n      - run: npm test\n      - run: npm run build\n",
 "README.md": "# Agent Flow Builder\n\nDraw a team of AI agents, get the [LangGraph](https://langchain-ai.github.io/langgraph/) code for it, and watch step by step how the graph runs.\nMade for **learning**: you do not need to know how to code to understand the flow, and you can copy the generated Python into your own project.\n\n- **Build** by dragging agents onto a canvas and connecting them. Pick a ready-made domain (hospitality, education, healthcare and more) or start blank.\n- **Read** the generated Python. Click any agent or arrow and the matching lines light up.\n- **Simulate** a run with no API key. You play the model and choose its answers, and the canvas shows where the run is.\n- **Learn** with a plain-English description of your own graph, a guide to reading the code, and a glossary.\n\nIt runs entirely in the browser. There is no server, no account, and no AI inside the app: the same design always produces the same code.\n\n## Quick start\n\nYou need [Node.js](https://nodejs.org) 20.19 or newer.\n\n```bash\nnpm install\nnpm run dev        # open the address it prints\n```\n\n| Command             | What it does                                           |\n| ------------------- | ------------------------------------------------------ |\n| `npm run dev`       | Start the app with live reload                         |\n| `npm run build`     | Build the site into `dist/`                            |\n| `npm run preview`   | Serve the built site locally                           |\n| `npm test`          | Run all tests once                                     |\n| `npm run test:watch`| Re-run tests as you edit                               |\n| `npm run typecheck` | Check the TypeScript types                             |\n\n## Project structure\n\n```\n.\n\u251c\u2500\u2500 index.html                  Page shell (Vite entry)\n\u251c\u2500\u2500 vite.config.ts              Build and test settings\n\u251c\u2500\u2500 public/favicon.svg\n\u251c\u2500\u2500 netlify.toml                Hosting settings for Netlify\n\u251c\u2500\u2500 .nvmrc                      Node version (22)\n\u251c\u2500\u2500 .github/workflows/ci.yml    Runs types, tests and a build on every push\n\u251c\u2500\u2500 src/\n\u2502   \u251c\u2500\u2500 main.tsx                Starts React\n\u2502   \u251c\u2500\u2500 App.tsx                 Layout: header, palette, canvas, side panel\n\u2502   \u251c\u2500\u2500 types.ts                Every shared type, in one place\n\u2502   \u2502\n\u2502   \u251c\u2500\u2500 data/                   Plain data. Edit these to change what the app offers.\n\u2502   \u2502   \u251c\u2500\u2500 domains.ts          The 15 domains and their ready-made agents\n\u2502   \u2502   \u251c\u2500\u2500 providers.ts        Gemini, Claude, OpenAI, Ollama settings\n\u2502   \u2502   \u2514\u2500\u2500 learn.ts            Glossary, experiments, code-section descriptions\n\u2502   \u2502\n\u2502   \u251c\u2500\u2500 logic/                  The brain. Pure functions: no React, no browser.\n\u2502   \u2502   \u251c\u2500\u2500 generate.ts         Graph -> Python code, line map and plan\n\u2502   \u2502   \u251c\u2500\u2500 explain.ts          Plan -> plain-English description\n\u2502   \u2502   \u251c\u2500\u2500 simulate.ts         Plan -> step-by-step simulation\n\u2502   \u2502   \u251c\u2500\u2500 graph.ts            Creating agents, ready-made teams, examples\n\u2502   \u2502   \u251c\u2500\u2500 connect.ts          Which arrows are allowed\n\u2502   \u2502   \u251c\u2500\u2500 placement.ts        Where a newly added agent goes\n\u2502   \u2502   \u251c\u2500\u2500 highlight.ts        Python syntax colouring (returns tokens, not HTML)\n\u2502   \u2502   \u251c\u2500\u2500 saveFile.ts         Save and open .json files (old saves still open)\n\u2502   \u2502   \u251c\u2500\u2500 helpers.ts          slug(), pyTriple(), ...\n\u2502   \u2502   \u2514\u2500\u2500 constants.ts\n\u2502   \u2502\n\u2502   \u251c\u2500\u2500 state/                  One reducer holds the whole app state\n\u2502   \u2502   \u251c\u2500\u2500 reducer.ts          State shape and every action\n\u2502   \u2502   \u251c\u2500\u2500 AppContext.tsx      Provider: runs generate(), the simulator and auto-play\n\u2502   \u2502   \u251c\u2500\u2500 selectors.ts        Small derived values\n\u2502   \u2502   \u251c\u2500\u2500 ToastContext.tsx    The short messages at the bottom\n\u2502   \u2502   \u2514\u2500\u2500 CanvasApi.tsx       Lets the palette ask the canvas where to drop an agent\n\u2502   \u2502\n\u2502   \u251c\u2500\u2500 hooks/\n\u2502   \u2502   \u251c\u2500\u2500 useActions.ts       Actions that need a check or a message (connect, add, open...)\n\u2502   \u2502   \u251c\u2500\u2500 useDeleteKey.ts     Delete key removes the selection\n\u2502   \u2502   \u251c\u2500\u2500 useFocusField.ts    Puts the cursor in the right field after a double-click\n\u2502   \u2502   \u2514\u2500\u2500 useLatest.ts\n\u2502   \u2502\n\u2502   \u251c\u2500\u2500 components/\n\u2502   \u2502   \u251c\u2500\u2500 layout/Header.tsx\n\u2502   \u2502   \u251c\u2500\u2500 palette/            Palette, PaletteRow, CustomAgents, LoadTeamButton, Legend\n\u2502   \u2502   \u251c\u2500\u2500 canvas/             Canvas, NodeView, ZoomBar, geometry.ts\n\u2502   \u2502   \u251c\u2500\u2500 panel/              SidePanel, LearnTab, CodeTab, CodeView, FocusBar, SimulateTab, AgentTab\n\u2502   \u2502   \u2514\u2500\u2500 ui/                 Rich (safe **bold** and `code`), TokenLine, PencilIcon\n\u2502   \u2502\n\u2502   \u251c\u2500\u2500 utils/                  download.ts, clipboard.ts\n\u2502   \u2514\u2500\u2500 styles/                 tokens, base, layout, palette, canvas, code, agent, simulate, learn, responsive\n\u2502\n\u2514\u2500\u2500 tests/                      Vitest. Logic, state and a render test of every tab and domain\n```\n\n## How it works\n\n```\n canvas  ->  design data  ->  generate()  ->  Python code\n (drag)      (nodes, edges)                -> line map   -> click an agent, see its lines\n                                           -> plan       -> explainGraph() and simCompute()\n```\n\n1. The canvas only edits a small object: agents (name, instructions, tools) and arrows (with optional conditions).\n2. `generate()` reads it and writes Python from templates. Along the way it records which line numbers belong to which agent or arrow (the **line map**) and builds a compact **plan** of the compiled graph.\n3. The explainer and the simulator read the plan. The simulator mirrors what LangGraph does: START, the supervisor chooses, an agent runs, control returns, FINISH, END.\n4. Everything is recomputed after every change, so the code, the explanation and the simulation always match the drawing.\n\nThe simulator and the generator are checked against each other in tests: the same choices give the same path.\n\n## Changing things\n\n| I want to...                         | Edit                                                                 |\n| ------------------------------------ | -------------------------------------------------------------------- |\n| Add a domain or change its agents    | `src/data/domains.ts` (each agent is `[name, what it does, tools]`)  |\n| Add an AI provider                   | `src/data/providers.ts`, then add its key to `ProviderKey` in `types.ts` |\n| Change the generated code            | `src/logic/generate.ts`, then update `tests/generate.test.ts`        |\n| Change the learning text             | `src/data/learn.ts` and `src/components/panel/LearnTab.tsx`          |\n| Add a new tab                        | add it to `TabName` in `types.ts`, then to `SidePanel.tsx`           |\n| Change colours                       | `src/styles/tokens.css` (light and dark mode)                        |\n\n**You do not need to add a domain for a new topic.** Choose *Custom (start blank)*, type what your team is for (for example \"cooking class\"), add a Supervisor, create your own agents with *Add your own*, and draw the arrows. The team name is used in the starting instructions of the Supervisor and of the agents you create. Agents you add by clicking line up in a column to the right of the Supervisor (see `src/logic/placement.ts`). Add a domain in code only when you want a ready-made team to load in one click.\n\nRule of thumb: anything about *what the code says* lives in `src/logic/` and is covered by tests. Anything about *how it looks or reacts* lives in `src/components/`.\n\n## Tests\n\n`npm test` runs, among others:\n\n- **Line map**: for every domain, with and without comments, each highlighted range really contains the code it claims to.\n- **Generated Python compiles**: every domain, provider and example is run through `python3 -m py_compile` (skipped if Python is not installed).\n- **Simulator**: paths, conditions, the recursion limit, Back, auto-play.\n- **State**: selection rules, ids, deleting, saving and opening (including saves from the first, single-file version).\n- **Render test**: the whole app is rendered for every tab and every domain, to catch crashes.\n\n## Deploy (GitHub + Netlify)\n\n1. **Check it locally first**: `npm install`, `npm test`, `npm run build`. This also creates `package-lock.json`, which you should commit.\n2. **Put it on GitHub**: create an empty repository (do not add a README or licence there, this project has them), then:\n   ```bash\n   git init\n   git add .\n   git commit -m \"Agent Flow Builder\"\n   git branch -M main\n   git remote add origin https://github.com/YOUR-NAME/agent-flow-builder.git\n   git push -u origin main\n   ```\n3. **Host it on Netlify**: Add new site > Import an existing project > GitHub > pick the repository. The settings come from `netlify.toml` (build command `npm run build`, publish folder `dist`). Press Deploy.\n4. From then on, every `git push` to `main` publishes a new version, and every pull request gets its own preview link.\n\nNo keys or environment variables are needed: the app never talks to any AI service.\n\n**Without GitHub**: run `npm run build`, then drag the `dist/` folder onto Netlify's deploy area.\n**Other hosts** (Cloudflare Pages, Vercel, GitHub Pages): build command `npm run build`, publish folder `dist`. The build uses relative paths, so it also works from a sub-folder.\n\n## Status and limits\n\n- The generated code is checked to be valid Python, and its routing is tested with stand-ins for LangGraph and the model. **It has not been run against a real model API.** Run it once with your own key before you tell anyone it works end to end.\n- Tools are empty stubs. The block at the bottom of the generated file is a demo: in your own app, import `graph` and call `graph.invoke(...)`.\n- The simulator uses placeholder replies. Real LangGraph runs parallel branches at the same time; the simulator runs them one after another and says so.\n\n## License\n\nMIT, see `LICENSE`.\n"
};

// Files the new version no longer has.
const REMOVE = ['.github/workflows/deploy.yml'];

const same = (p, text) => existsSync(p) && readFileSync(p, 'utf8').replace(/\r\n/g, '\n') === text;

let updated = 0;
for (const [rel, text] of Object.entries(FILES)) {
  const p = join(root, rel);
  if (same(p, text)) continue;
  mkdirSync(dirname(p), { recursive: true });
  writeFileSync(p, text);
  updated++;
  console.log('  updated  ' + rel);
}
for (const rel of REMOVE) {
  const p = join(root, rel);
  if (existsSync(p)) { rmSync(p); updated++; console.log('  removed  ' + rel); }
}
console.log(updated ? `\nDone: ${updated} file(s) changed. Now run: npm test` : '\nAlready up to date. Nothing to change.');
console.log('You can delete apply-update.mjs now.');
